    // An SVG data URI for one of the app's own symbols, or nil for an SF Symbol, since SF Symbols'
    // license only covers Apple platforms
    static func iconDataURI(symbol: String) -> String? {
        guard let path = iconPaths[symbol] else { return nil }
        let svg = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 -960 960 960\"><path d=\"\(path)\"/></svg>"
        return "data:image/svg+xml;base64," + Data(svg.utf8).base64EncodedString()
    }

    // The properties a trip record gets for its mode's icon: the icon itself if it's one of the
    // app's own, or else the SF Symbol's name
    @objc(iconPropertiesForModeID:) static func iconProperties(_ id: String) -> [String: String] {
        let symbol = self.symbol(id)
        if let icon = iconDataURI(symbol: symbol) {
            return ["icon": icon]
        }
        return ["sf_symbol": symbol]
    }
